package com.bloodlink.repository.jdbc;
import com.bloodlink.db.Database; import com.bloodlink.model.*; import com.bloodlink.repository.AppointmentRepository; import java.sql.*; import java.util.*;
public final class JdbcAppointmentRepository implements AppointmentRepository {
 public List<Appointment> findAll(){List<Appointment>x=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM appointments ORDER BY appointment_date,appointment_time")){while(r.next())x.add(new Appointment(r.getInt("id"),r.getString("donor_name"),BloodGroup.from(r.getString("blood_group")),r.getDate("appointment_date").toLocalDate(),r.getTime("appointment_time").toLocalTime(),r.getString("branch"),r.getString("status")));}catch(SQLException e){throw new RuntimeException(e);}return x;}
 public Appointment save(Appointment a){String q="INSERT INTO appointments(donor_name,blood_group,appointment_date,appointment_time,branch,status) VALUES(?,?,?,?,?,?)";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,a.getDonorName());p.setString(2,a.getBloodGroup().toString());p.setDate(3,java.sql.Date.valueOf(a.getDate()));p.setTime(4,Time.valueOf(a.getTime()));p.setString(5,a.getBranch());p.setString(6,a.getStatus());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next())a.setId(k.getInt(1));}return a;}catch(SQLException e){throw new RuntimeException(e);}}
 public void update(Appointment a){try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET status=? WHERE id=?")){p.setString(1,a.getStatus());p.setInt(2,a.getId());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
}
